CREATE OR REPLACE FUNCTION trip_private.quest_unlocked(p_trip uuid,p_week integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$ SELECT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=p_week AND NOT n.skipped AND now()>=(trip_private.season_start(p_trip)::timestamp AT TIME ZONE (SELECT t.home_timezone FROM public.trips t WHERE t.id=p_trip)) AND (n.week_number=(SELECT min(x.week_number) FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped) OR EXISTS(SELECT 1 FROM public.game_nights prev WHERE prev.trip_id=p_trip AND NOT prev.skipped AND prev.week_number<n.week_number AND prev.starts_at+interval '3 hours 30 minutes'<=now() AND NOT EXISTS(SELECT 1 FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped AND x.week_number>prev.week_number AND x.week_number<n.week_number)))) $$;
CREATE OR REPLACE FUNCTION trip_private.carry_quest_unlocked(p_trip uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='public' AS $$ SELECT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped AND n.week_number=(SELECT max(x.week_number) FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped) AND n.starts_at+interval '3 hours 30 minutes'<=now()) $$;
DROP POLICY season_quests_read ON public.season_quests;
CREATE POLICY season_quests_read ON public.season_quests FOR SELECT TO authenticated USING (trip_private.is_trip_member(trip_id,auth.uid()) AND ((user_id=auth.uid() AND ((quest_kind='preflight' AND trip_private.quest_unlocked(trip_id,night_week)) OR (quest_kind='carry_on' AND trip_private.carry_quest_unlocked(trip_id)))) OR (trip_private.is_leader(trip_id) AND status='pending')));
CREATE OR REPLACE FUNCTION trip_private.ensure_season_quests(p_trip uuid,p_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE t public.trips; n record; v_count int; v_i int:=0; v_legacy int; v_budget int; v_points int; v_card public.security_missions; v_dest text; BEGIN
 IF auth.uid() IS DISTINCT FROM p_user OR NOT trip_private.is_trip_member(p_trip,p_user) THEN RAISE EXCEPTION 'Only approved members can see quests'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip; IF NOT FOUND THEN RAISE EXCEPTION 'Trip not found'; END IF;
 IF now() < (trip_private.season_start(p_trip)::timestamp AT TIME ZONE t.home_timezone) THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p_trip::text||p_user::text||'quests'));
 SELECT count(*) INTO v_count FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped;
 SELECT coalesce(sum(points),0)::int INTO v_legacy FROM public.mission_claims WHERE trip_id=p_trip AND user_id=p_user AND phase='checkin' AND status IN ('pending','released');
 v_budget:=greatest(0,least(12,greatest(10,v_count))-v_legacy);
 v_dest:=coalesce(nullif(t.destination,''),nullif(t.at_home_pack,''),'your destination');
 FOR n IN SELECT week_number,starts_at FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped ORDER BY week_number LOOP
  v_i:=v_i+1;
  IF NOT trip_private.quest_unlocked(p_trip,n.week_number) THEN EXIT; END IF;
  IF EXISTS(SELECT 1 FROM public.season_quests q WHERE q.trip_id=p_trip AND q.user_id=p_user AND q.quest_kind='preflight' AND q.night_week=n.week_number) THEN CONTINUE; END IF;
  SELECT * INTO v_card FROM public.security_missions sm WHERE sm.kind='checkin' AND sm.trip_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.season_quests existing WHERE existing.trip_id=p_trip AND existing.user_id=p_user AND existing.title=replace(sm.title,'{destination}',v_dest)) ORDER BY md5(sm.id::text||p_trip::text||p_user::text||v_i::text) LIMIT 1;
  IF NOT FOUND THEN EXIT; END IF;
  v_points:=CASE WHEN v_count>10 THEN 1 ELSE 10/v_count+CASE WHEN v_i<=10%v_count THEN 1 ELSE 0 END END;
  v_points:=greatest(0,least(v_points,v_budget)); v_budget:=greatest(0,v_budget-v_points);
  INSERT INTO public.season_quests(trip_id,user_id,quest_kind,night_week,title,mission_text,backstory,keywords,points) VALUES(p_trip,p_user,'preflight',n.week_number,replace(coalesce(v_card.title,'Discover the destination'),'{destination}',v_dest),replace(coalesce(v_card.text,''),'{destination}',v_dest),replace(coalesce(v_card.backstory,''),'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(v_card.keywords) k),v_points) ON CONFLICT DO NOTHING;
 END LOOP;
 IF t.kind IS DISTINCT FROM 'at_home' AND v_count>0 AND trip_private.carry_quest_unlocked(p_trip) AND NOT EXISTS(SELECT 1 FROM public.season_quests q WHERE q.trip_id=p_trip AND q.user_id=p_user AND q.quest_kind='carry_on') THEN
  SELECT * INTO v_card FROM public.security_missions sm WHERE sm.kind='checkin' AND sm.trip_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.season_quests existing WHERE existing.trip_id=p_trip AND existing.user_id=p_user AND existing.title=replace(sm.title,'{destination}',v_dest)) ORDER BY md5(sm.id::text||p_trip::text||p_user::text||'carry') LIMIT 1;
  IF FOUND THEN INSERT INTO public.season_quests(trip_id,user_id,quest_kind,title,mission_text,backstory,keywords,points) VALUES(p_trip,p_user,'carry_on',replace(coalesce(v_card.title,'Discover the destination'),'{destination}',v_dest),replace(coalesce(v_card.text,''),'{destination}',v_dest),replace(coalesce(v_card.backstory,''),'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(v_card.keywords) k),5) ON CONFLICT DO NOTHING; END IF;
 END IF;
 END $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_action(p_trip uuid,p_quest uuid,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ DECLARE q public.season_quests; n public.game_nights; t public.trips; ss public.season_settings; BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
 SELECT * INTO q FROM public.season_quests WHERE id=p_quest AND trip_id=p_trip FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Quest not found'; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF q.quest_kind='preflight' THEN SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=q.night_week AND NOT skipped; IF NOT FOUND OR NOT trip_private.quest_unlocked(p_trip,q.night_week) THEN RAISE EXCEPTION 'This quest is not unlocked'; END IF; IF p_action IN ('approve','decline') AND NOT (trip_private.night_open(p_trip,q.night_week) OR now()>=n.starts_at) THEN RAISE EXCEPTION 'Present this quest on game night'; END IF;
 ELSE SELECT * INTO ss FROM public.season_settings WHERE trip_id=p_trip AND season='trip'; IF NOT trip_private.carry_quest_unlocked(p_trip) OR ss.carry_on_meetup_at IS NULL OR now()<ss.carry_on_meetup_at OR (now() AT TIME ZONE t.trip_timezone)::date NOT BETWEEN t.start_date AND t.end_date THEN RAISE EXCEPTION 'The Carry-On meet-up must happen during the Trip'; END IF; END IF;
 IF p_action='complete' THEN IF q.user_id<>auth.uid() OR q.status NOT IN ('new','declined') THEN RAISE EXCEPTION 'Only your open quest can be marked done'; END IF; UPDATE public.season_quests SET status='pending',presented_at=now() WHERE id=p_quest AND trip_id=p_trip;
 ELSIF p_action IN ('approve','decline') THEN IF NOT trip_private.is_leader(p_trip) OR q.user_id=auth.uid() THEN RAISE EXCEPTION 'Another Captain or Co-Captain must review this quest'; END IF; IF q.status<>'pending' THEN RAISE EXCEPTION 'Quest is not waiting for review'; END IF; IF p_action='approve' THEN IF q.quest_kind='preflight' AND EXISTS(SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season='game') THEN RAISE EXCEPTION 'The Pre-Flight crown is already final'; END IF; UPDATE public.season_quests SET status='approved',approved_at=now(),approved_by=auth.uid(),awarded_points=points WHERE id=p_quest AND trip_id=p_trip; ELSE UPDATE public.season_quests SET status='declined',presented_at=NULL WHERE id=p_quest AND trip_id=p_trip; END IF;
 ELSE RAISE EXCEPTION 'Unknown quest action'; END IF; END $$;
CREATE OR REPLACE FUNCTION trip_private.season_quest_current(p_trip uuid) RETURNS TABLE(id uuid,user_id uuid,kind text,night_week integer,title text,mission_text text,backstory text,keywords text[],points integer,status text,starts_at timestamptz,place text,total integer,completed integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path='public' AS $$ BEGIN
 PERFORM trip_private.ensure_season_quests(p_trip,auth.uid());
 RETURN QUERY SELECT q.id,q.user_id,q.quest_kind,q.night_week,q.title,q.mission_text,q.backstory,q.keywords,q.points,q.status,CASE WHEN q.quest_kind='carry_on' THEN ss.carry_on_meetup_at ELSE n.starts_at END,CASE WHEN q.quest_kind='carry_on' THEN ss.carry_on_meetup_place ELSE coalesce(n.place,'Video call') END,(SELECT count(*)::int FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped),(SELECT count(*)::int FROM public.season_quests x WHERE x.trip_id=p_trip AND x.user_id=auth.uid() AND x.quest_kind='preflight' AND x.status='approved') FROM public.season_quests q LEFT JOIN public.game_nights n ON n.trip_id=q.trip_id AND n.week_number=q.night_week LEFT JOIN public.season_settings ss ON ss.trip_id=q.trip_id AND ss.season='trip' WHERE q.trip_id=p_trip AND q.user_id=auth.uid() AND ((q.quest_kind='carry_on' AND trip_private.carry_quest_unlocked(p_trip)) OR (q.quest_kind='preflight' AND trip_private.quest_unlocked(p_trip,q.night_week))) ORDER BY CASE WHEN q.status IN ('new','declined','pending') THEN 0 ELSE 1 END,CASE WHEN q.quest_kind='preflight' THEN 0 ELSE 1 END,q.night_week ASC NULLS LAST LIMIT 1;
 END $$;
REVOKE ALL ON FUNCTION trip_private.quest_unlocked(uuid,integer),trip_private.carry_quest_unlocked(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.quest_unlocked(uuid,integer),trip_private.carry_quest_unlocked(uuid) TO authenticated,service_role;